read -r _ user nice system idle iowait irq softirq steal _ _ < /proc/stat; total1=$((user + nice + system + idle + iowait + irq + softirq + steal)); idle1=$((idle + iowait)); sleep 0.25; read -r _ user nice system idle iowait irq softirq steal _ _ < /proc/stat; total2=$((user + nice + system + idle + iowait + irq + softirq + steal)); idle2=$((idle + iowait)); awk -v t1="$total1" -v t2="$total2" -v i1="$idle1" -v i2="$idle2" 'BEGIN { if (t2 > t1) printf "CPU=%.1f\n", (1 - (i2-i1)/(t2-t1))*100 }'; read -r load1 load5 load15 _ < /proc/loadavg; printf 'LOAD=%s %s %s\n' "$load1" "$load5" "$load15"; printf 'CORES=%s\n' "$(nproc 2>/dev/null || getconf _NPROCESSORS_ONLN 2>/dev/null)"; awk '/^MemTotal:/ {total=$2} /^MemAvailable:/ {available=$2} END {if (total > 0 && available >= 0) printf "RAM=%.2f %.2f\n", (total-available)/1048576, total/1048576}' /proc/meminfo; df -Pk / | awk 'NR == 2 {printf "DISK=%.2f %.2f %s\n", $3/1048576, $2/1048576, $6}'; awk -F': ' '/model name/ {print "CPUMODEL=" $2; exit}' /proc/cpuinfo 2>/dev/null; awk -F': ' '/cpu MHz/ {printf "CPUFREQ=%.1f GHz\n", $2/1000; exit}' /proc/cpuinfo 2>/dev/null; awk '/^Active:/ {active=$2} /^Buffers:/ {buffers=$2} /^Cached:/ {cached=$2} /^SwapTotal:/ {st=$2} /^SwapFree:/ {sf=$2} END {printf "RAMDETAIL=%.2f %.2f %.2f %.2f\n", active/1048576, (buffers+cached)/1048576, (st-sf)/1048576, st/1048576}' /proc/meminfo 2>/dev/null; awk 'NR>2 && !/lo:|docker|br-|veth/ {sub(/:/, "", $1); printf "NET=%s %s %s %s\n", $1, $2, $10, $4+$12; exit}' /proc/net/dev 2>/dev/null; uptime -p 2>/dev/null | sed 's/^/UPTIME=/';
